package org.pms.silverocean.database.pms;
import org.pms.silverocean.database.pms.entities.AffiliateCommission;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.data.domain.Pageable;import java.time.ZonedDateTime;import java.util.List;
public interface AffiliateCommissionRepo extends JpaRepository<AffiliateCommission,Long>{boolean existsByInvoiceId(long invoiceId);java.util.Optional<AffiliateCommission> findByInvoiceId(long invoiceId);List<AffiliateCommission> findAllByReferredUserIdAndActiveTrueOrderByEarnedAtAsc(long referredUserId);List<AffiliateCommission> findAllByAffiliateUserIdAndActiveTrueOrderByCreatedOnDesc(long id);List<AffiliateCommission> findAllByAffiliateUserIdAndStatusAndActiveTrue(long id,String status);List<AffiliateCommission> findAllByPayoutIdAndActiveTrue(long payoutId);@Query("SELECT c FROM AffiliateCommission c WHERE c.active AND c.createdOn>=:start AND c.createdOn<:end AND (:privileged=true OR c.affiliateUserId=:userId) ORDER BY c.createdOn DESC")List<AffiliateCommission> findForReport(long userId,boolean privileged,ZonedDateTime start,ZonedDateTime end,Pageable pageable);}
